	.byte 0x08, 0x99, 0x00	; LD (T4FFCR), 000h
	.byte 0x08, 0x9f, 0x00	; LD (T16CR), 000h
	.byte 0x0a, 0x90, 0x01, 0x00	; LDW (TREG4L:24), 0001h (ASL unsupported)
