	.byte 0xf0, 0x9e, 0xbf	; SET 7, (T16RUN)
	.byte 0xf0, 0x9e, 0xb8	; SET 0, (T16RUN)

	; === Memory Controller: Start Address Registers ===
	.byte 0xf1, 0x43, 0x01, 0x00, 0x1e	; LD (MSAR0), 01eh	; Block 0 @ 0x1E0000
	.byte 0xf1, 0x47, 0x01, 0x00, 0x10	; LD (MSAR1), 010h	; Block 1 @ 0x100000
	.byte 0xf1, 0x4b, 0x01, 0x00, 0xc0	; LD (MSAR2), 0c0h	; Block 2 @ 0xC00000
	.byte 0xf1, 0x4f, 0x01, 0x00, 0x00	; LD (MSAR3), 000h	; Block 3 @ 0x000000
	.byte 0xf1, 0x53, 0x01, 0x00, 0x80	; LD (MSAR4), 080h	; Block 4 @ 0x800000 (Table Data)
	.byte 0xf1, 0x57, 0x01, 0x00, 0x00	; LD (MSAR5), 000h	; Block 5 @ 0x000000

