; ===========================================================================
; SubCPU_Payload_Verify - Verify Sub-CPU firmware payload integrity
; ===========================================================================
; Entry: Sub-CPU firmware payload has been transferred
; Exit:  Error flag at 0x01E53E set to indicate result:
;          0x00 = Both checksums match (success)
;          0x01 = First checksum mismatch, second matches (partial error)
;          0xFF = Checksum verification failed (error)
; Notes: Computes checksums over two memory regions and compares against
;        expected values stored at boot. On failure, the error flag triggers
;        the "ERROR in CPU data transmission" dialog during boot.
;
; See also:
;   - SubCPU_Send_Payload - Transfers the firmware payload
;   - SubCPU_Payload_GetErrorFlag - Reads the error flag
;   - ErrorDialog_CPUTransmissionError - Error dialog shown on failure
; ===========================================================================
SubCPU_Payload_Verify:	; EF092B
LABEL_EF092B:
	ld xwa, 0xF180	; Start of payload region 1
	.byte 0x31, 0x00, 0x08	; LD BC, 0800h	; Size: 0x800 words
	call LABEL_EF18E7	; Compute checksum -> HL
	.byte 0xf2, 0x80, 0xf9, 0x00, 0x30	; LDA XWA, 0F980h:24
	.byte 0xd2, 0xd4, 0xff, 0x00, 0xf3	; CP HL, (0FFD4h:24)	; Compare with expected checksum
	.byte 0x6e, 0x1b	; JR NZ, SubCPU_Payload_Verify_Fail	; First region checksum failed
	.byte 0xf2, 0x3e, 0xe5, 0x01, 0x00, 0x00	; LD (01E53Eh), 000h	; Mark as success (so far)
	.byte 0x31, 0x80, 0x02	; LD BC, 0280h	; Size of second region
	call LABEL_EF18E7	; Compute second checksum
	.byte 0xd2, 0xd2, 0xff, 0x00, 0xf3	; CP HL, (0FFD2h:24)	; Compare with expected
	.byte 0xb0, 0xf6	; RET Z	; Both match -> success
	.byte 0xf2, 0x3e, 0xe5, 0x01, 0x00, 0xff	; LD (01E53Eh), 0ffh	; Second region failed
	ret

SubCPU_Payload_Verify_Fail:	; EF095E
LABEL_EF095E:
	.byte 0xf2, 0x3e, 0xe5, 0x01, 0x00, 0xff	; LD (01E53Eh), 0ffh	; Mark as failed
	.byte 0x31, 0x80, 0x02	; LD BC, 0280h
	call LABEL_EF18E7
	.byte 0xd2, 0xd2, 0xff, 0x00, 0xf3	; CP HL, (0FFD2h:24)
	.byte 0xb0, 0xfe	; RET NZ	; Both checksums wrong
	.byte 0xf2, 0x3e, 0xe5, 0x01, 0x00, 0x01	; LD (01E53Eh), 001h	; First wrong, second correct (partial)
	ret

