; ===========================================================================
; SubCPU_Init_DMA_Channels - Initialize DMA channels for inter-CPU communication
; ===========================================================================
; Entry: None
; Exit:  DMA channels configured for Sub-CPU payload transfer
; Notes: Sets up MicroDMA channels 0 and 2 for inter-CPU latch communication
;        - DMA channel 2 destination = latch at 0x140000 (Main→Sub)
;        - DMA channel 0 source = latch at 0x140000 (Sub→Main)
;        - Configures interrupt priorities for DMA completion
;        - Clears transfer state variables at 0x05E0 and 0x05E2
;        Called during boot after Sub-CPU is released from reset
; ===========================================================================
SubCPU_Init_DMA_Channels:
	.byte 0xc0, 0xe5, 0x3c, 0xf8	; AND (INTET23), 0f8h
	.byte 0xf0, 0x80, 0xb2	; RES 2, (T8RUN)
	.byte 0xf0, 0xec, 0x31	; LDA XBC, INTETC01
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	.byte 0xf0, 0xed, 0x31	; LDA XBC, INTETC23
	ld a, (xbc)
	and a, 0xF8
	or a, 0x5
	ld (xbc), a
	.byte 0xf0, 0xf0, 0x31	; LDA XBC, INTE0AD
	ld a, (xbc)
	and a, 0xF8
	.byte 0xc9, 0x31, 0x00	; SET 000h, A
	ld (xbc), a
	.byte 0x08, 0x8a, 0x07	; LD (TREG2), 007h
	.byte 0xf2, 0x00, 0x00, 0x14, 0x30	; LDA XWA, INTER_CPU_COMM_LATCHES
	.byte 0xe8, 0x2e, 0x28	; LDC_DMAD2_XWA
	.byte 0x21, 0x08	; LD_A 008h
	.byte 0xc9, 0x2e, 0x4a	; LDC_DMAM2_A
	.byte 0xf2, 0x00, 0x00, 0x14, 0x30	; LDA XWA, INTER_CPU_COMM_LATCHES
	.byte 0xe8, 0x2e, 0x00	; LDC_DMAS0_XWA
	.byte 0x21, 0x00	; LD_A 000h
	.byte 0xc9, 0x2e, 0x42	; LDC_DMAM0_A
	.byte 0xf1, 0xe0, 0x05, 0x00, 0x00	; LD (05E0h), 000h
	.byte 0xf1, 0xe2, 0x05, 0x00, 0x00	; LD (05E2h), 000h
	ret
