; == Notes ==
; This routine can be summarized as this sequence of memory writes:
; [00815554h] = 00aa00aah
; [0080aaa8h] = 00550055h
; [00815554h] = 00800080h
; [00815554h] = 00aa00aah
; [0080aaa8h] = 00550055h
; [00815554h] = 00100010h
;
; addresses:   ----------------| |||||||| ||||||--
; 00815554h = 00000000 10000001 01010101 01010100
; 0080aaa8h = 00000000 10000000 10101010 10101000
;
; data values: -------- |||||||| -------- ||||||||
; 00550055h = 00000000 01010101 00000000 01010101
; 00aa00aah = 00000000 10101010 00000000 10101010
; 00800080h = 00000000 10000000 00000000 10000000
; 00100010h = 00000000 00010000 00000000 00010000

	; [00815554h] = 00aa00aah
	ld xbc, xiz
	add xbc, 0x15554
	ld xwa, 0xAA00AA
	ld (xbc), xwa

	; [0080aaa8h] = 00550055h
	ld xbc, xiz
	add xbc, 0xAAA8
	ld xwa, 0x550055
	ld (xbc), xwa

	; [00815554h] = 00800080h
	ld xbc, xiz
	add xbc, 0x15554
	ld xwa, 0x800080
	ld (xbc), xwa

	; [00815554h] = 00aa00aah
	ld xbc, xiz
	add xbc, 0x15554
	ld xwa, 0xAA00AA
	ld (xbc), xwa

	; [0080aaa8h] = 00550055h
	ld xbc, xiz
	add xbc, 0xAAA8
	ld xwa, 0x550055
	ld (xbc), xwa

	; [00815554h] = 00100010h
	ld xbc, xiz
	add xbc, 0x15554
	ld xwa, 0x100010
	ld (xbc), xwa

	.byte 0x06, 0x00	; EI 000h
	pop xiz
	ret

