	.byte 0x30, 0xc9, 0x03	; LD WA, 3c9h
	.byte 0xd9, 0xac	; LDW BC, 4
	.byte 0x1e, 0x4d, 0xf6	; CALR Write_VGA_Register

	; Call extended sequencer init
	.byte 0x1e, 0x6c, 0xf6	; CALR VGA_Extended_Init

	; Set up parameters for video buffer initialization
	; These are loaded here; caller provides the actual CALL to fill/copy routines
	.byte 0x40, 0x00, 0x3c, 0x04, 0x00	; LD XWA, OFFSCREEN_BUFFER_1
	.byte 0x31, 0x08, 0x08	; LD BC, 0808h	; Fill pattern
	.byte 0x32, 0x00, 0x96	; LD DE, 320 * 240 / 2	; Size in words (38400 = 0x9600)

	; === End of shared VGA init code ===
	; Each ROM must now:
	;   1. CALL its memory fill routine (fills XWA with DE words of BC pattern)
	;   2. LDA XWA, VIDEO_RAM_BASE
	;   3. LD XBC, OFFSCREEN_BUFFER_1
	;   4. LD DE, 320 * 240 / 2
	;   5. CALL its memory copy routine
	;   6. RET_VGA_SEQUENCER 01h, 001h  (turn screen on)
; --- end include: ../shared/vga_init.asm ---
; Aliases for external references using original label names
.equ LABEL_EF5163, VGA_Extended_Init
.equ Some_VGA_setup, VGA_Setup

	; === ROM-specific ending: initialize video buffers ===
	call Fill_memory_at_XWA_with_DE_words_of_BC_value
	.byte 0xf2, 0x00, 0x00, 0x1a, 0x30	; LDA XWA, VIDEO_RAM_BASE
	.byte 0x41, 0x00, 0x3c, 0x04, 0x00	; LD XBC, OFFSCREEN_BUFFER_1
	.byte 0x32, 0x00, 0x96	; LD DE, 320 * 240 / 2
	call Copy_DE_words_from_XBC_to_XWA	; Blit video buffer

	.byte 0x30, 0xc4, 0x03, 0xd9, 0xa9, 0x1e, 0x22, 0xf6, 0x30, 0xc5, 0x03, 0xd9, 0xa9, 0x78, 0x1a, 0xf6	; RET_VGA_SEQUENCER 01h, 001h	; Clocking Mode (screen on)


