; -----------------------------------------------------------------------------
; Wallpaper Name Getter Routines
; -----------------------------------------------------------------------------
; These routines retrieve wallpaper display names from various sources:
; - User RAM structures (0x1ED350, 0x1E0000, 0x1E4980, 0x1E4AA7)
; - ROM lookup tables (0xEA07AE, 0xEA07EA, 0xEA083E, 0xEA08DA)
;
; Common calling convention:
;   XWA = destination buffer pointer
;   BC = index or selection parameter
;   E = type marker byte
; -----------------------------------------------------------------------------

; Get wallpaper name from config structure by index
; Input: XWA = dest buffer, BC = index, E = type marker
WP_GetConfigName:
	push xiz
	ld xiz, xwa
	.byte 0xf2, 0x50, 0xd3, 0x1e, 0x33	; LDA XHL, 01ED350h	; Wallpaper config base address
	extz xbc
	.byte 0xe9, 0xee, 0x04	; SLL 4, XBC	; index * 16
	add xhl, xbc
	.byte 0xbb, 0x10, 0x33	; LDA XHL, XHL + 010h	; Offset to name field
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E	; Store type marker
	ld xwa, xiz
	ld xbc, xhl
	.byte 0x32, 0x10, 0x00	; LD DE, 0010h	; Copy 16 bytes
	call LABEL_F890F2
	.byte 0xbe, 0x10, 0x00, 0x00	; LD (XIZ + 010h), 000h	; Null terminate
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0x98, 0xf1	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Get wallpaper name with calculated offset
; Input: XWA = dest buffer, BC = multiplier, E = type marker
WP_GetNameByOffset:
	push xiz
	ld xiz, xwa
	.byte 0xf2, 0x50, 0xd3, 0x1e, 0x30	; LDA XWA, 01ED350h
	.byte 0x98, 0x0d, 0x23	; LD HL, (XWA + 00Dh)	; Get entry size from config
	ld xix, xwa
	.byte 0xd9, 0x43	; MUL XHL, BC	; Calculate offset
	add xix, xhl
	.byte 0xf3, 0xf1, 0xb2, 0x00, 0x31	; LDA XBC, XIX + 0B2h	; Offset to name field
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	ld xwa, xiz
	.byte 0x32, 0x10, 0x00	; LD DE, 0010h
	call LABEL_F890F2
	.byte 0xbe, 0x10, 0x00, 0x00	; LD (XIZ + 010h), 000h
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0x68, 0xf1	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Get wallpaper name from ROM table 1 (0xEA07AE)
; Input: XWA = dest buffer, BC = index, E = type marker
WP_GetPresetName1:
	push xiz
	ld xiz, xwa
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	ld wa, bc
	extz xwa
	.byte 0xe8, 0xee, 0x02	; SLL 2, XWA	; index * 4 (pointer size)
	ld xbc, 0xEA07AE	; ROM table address
	add xbc, xwa
	ld xbc, (xbc)	; Get string pointer
	ld xwa, xiz
	call LABEL_F890DC
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0x42, 0xf1	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Simple wallpaper pointer lookup from ROM table 2 (0xEA07EA)
; Input: WA = index
; Output: XHL = pointer to name string
WP_GetPresetPtr:
	extz xwa
	.byte 0xe8, 0xee, 0x02	; SLL 2, XWA	; index * 4
	ld xbc, 0xEA07EA
	add xbc, xwa
	ld xhl, (xbc)
	ret

; Get wallpaper name with bank/memory selection
; Input: XWA = dest buffer, BC = bank, DE = memory slot, stack+8 = type marker
WP_GetBankMemName:
	push xiz
	ld hl, bc
	ld xiz, xwa
	.byte 0xf5, 0xf8, 0x31	; LDA XBC, XIZ+
	.byte 0x9f, 0x08, 0x20	; LD WA, (XSP + 008h)
	ld (xbc), a	; Store type marker
	.byte 0xda, 0xdc	; CP DE, 4
	.byte 0x6f, 0x1f	; JR NC, WP_GetBankMemName_FromROM
	; From RAM at 0x0948A0
	.byte 0xf2, 0xa0, 0x48, 0x09, 0x31	; LDA XBC, 0948A0h
	.byte 0xdb, 0xee, 0x02	; SLL 2, HL
	add hl, de
	.byte 0xdb, 0x08, 0x60, 0x00	; MUL_HL 0060h	; Entry size = 96 bytes
	add xbc, xhl
	ld xwa, xiz
	.byte 0x32, 0x0d, 0x00	; LD DE, 000Dh	; Copy 13 bytes
	call LABEL_F890F2
	.byte 0xbe, 0x0d, 0x00, 0x00	; LD (XIZ + 00Dh), 000h
	.byte 0x68, 0x14	; JR T, WP_GetBankMemName_Format
WP_GetBankMemName_FromROM:
	extz xde
	.byte 0xea, 0xee, 0x02	; SLL 2, XDE
	ld xbc, 0xEA083E	; ROM table address
	add xbc, xde
	ld xbc, (xbc)
	ld xwa, xiz
	call LABEL_F890DC
WP_GetBankMemName_Format:
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0xe5, 0xf0	; CALR TrimAndPadSmfFilename
	pop xiz
	.byte 0x0f, 0x02, 0x00	; RETD 2

; Get wallpaper name from ROM table 3 (0xEA08DA)
; Input: XWA = dest buffer, BC = index, E = type marker
WP_GetPresetName3:
	push xiz
	ld xiz, xwa
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	ld wa, bc
	extz xwa
	.byte 0xe8, 0xee, 0x02	; SLL 2, XWA
	ld xbc, 0xEA08DA
	add xbc, xwa
	ld xbc, (xbc)
	ld xwa, xiz
	call LABEL_F890DC
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0xbd, 0xf0	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Get wallpaper name from structure at 0x1E0000 (stride 0x1D6)
; Input: XWA = dest buffer, BC = index, E = type marker
WP_GetUserName1:
	push xiz
	ld xiz, xwa
	.byte 0xf2, 0x00, 0x00, 0x1e, 0x33	; LDA XHL, 01E0000h
	.byte 0xbb, 0x10, 0x33	; LDA XHL, XHL + 010h
	.byte 0xd9, 0x08, 0xd6, 0x01	; MUL_BC 01D6h	; Entry stride
	add xhl, xbc
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	ld xwa, xiz
	ld xbc, xhl
	.byte 0x32, 0x10, 0x00	; LD DE, 0010h
	call LABEL_F890F2
	.byte 0xbe, 0x10, 0x00, 0x00	; LD (XIZ + 010h), 000h
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0x90, 0xf0	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Get wallpaper name from RAM at 0x1E4980
; Input: XWA = dest buffer, BC = (unused), E = type marker
WP_GetUserName2:
	push xiz
	ld de, bc
	ld xiz, xwa
	.byte 0xf2, 0x80, 0x49, 0x1e, 0x31	; LDA XBC, 01E4980h
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	ld xwa, xiz
	.byte 0x32, 0x10, 0x00	; LD DE, 0010h
	call LABEL_F890F2
	.byte 0xbe, 0x10, 0x00, 0x00	; LD (XIZ + 010h), 000h
	ld xwa, xiz
	.byte 0x31, 0x10, 0x00	; LD BC, 0010h
	.byte 0x1e, 0x6c, 0xf0	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

; Get wallpaper name from structure at 0x1E4AA7 (stride 0x50)
; Input: XWA = dest buffer, BC = index, E = type marker
WP_GetUserName3:
	push xiz
	ld xiz, xwa
	.byte 0xf2, 0xa7, 0x4a, 0x1e, 0x33	; LDA XHL, 01E4AA7h
	.byte 0xd9, 0x08, 0x50, 0x00	; MUL_BC 0050h	; Entry stride
	add xhl, xbc
	.byte 0xf5, 0xf8, 0x45	; LD (XIZ+), E
	.byte 0xf5, 0xf8, 0x00, 0x20	; LD (XIZ+), 020h	; Space character
	ld xwa, xiz
	ld xbc, xhl
	.byte 0x32, 0x0d, 0x00	; LD DE, 000Dh	; Copy 13 bytes
	call LABEL_F890F2
	.byte 0xbe, 0x0d, 0x00, 0x00	; LD (XIZ + 00Dh), 000h
	ld xwa, xiz
	.byte 0x31, 0x0f, 0x00	; LD BC, 000Fh
	.byte 0x1e, 0x3e, 0xf0	; CALR TrimAndPadSmfFilename
	pop xiz
	ret

