FmmSeqSongNameFunc:
	.byte 0x2e	; PUSH IZ
	cp xbc, 0x1E50003
	.byte 0x76, 0x5c, 0x02	; JRL Z, SeqName_GetIndexReturn
	.byte 0xd1, 0xd8, 0x82, 0x23	; LD HL, (82D8h)
	cp xbc, 0x1E50002
	.byte 0x76, 0xfd, 0x01	; JRL Z, SeqName_SetIndexPlaying
	cp xbc, 0x1C00018
	.byte 0x66, 0x62	; JR Z, SeqName_HandleNavigation
	cp xbc, 0x1C00017
	.byte 0x66, 0x5a	; JR Z, SeqName_HandleNavigation
	cp xbc, 0x1C0000B
	.byte 0x66, 0x2b	; JR Z, SeqName_InitAllSlots
	cp xbc, 0x1E50004
	.byte 0x6e, 0x45	; JR NZ, SeqName_ReturnZero
	.byte 0xf1, 0xd4, 0x82, 0x62	; LD (82D4h), XDE
	.byte 0xc1, 0xfe, 0x84, 0x3f, 0x00	; CP (84FEh), 000h
	.byte 0x6e, 0x06	; JR NZ, SeqName_SendCurrentIndex
	.byte 0xf1, 0xd8, 0x82, 0x02, 0x00, 0x00	; LDW (82D8h), 0000h

SeqName_SendCurrentIndex:
	.byte 0xd1, 0xd8, 0x82, 0x22	; LD DE, (82D8h)
	extz xde
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1E50002
	.byte 0x78, 0x05, 0x02	; JRL T, SeqName_PostEventExit

SeqName_InitAllSlots:
	.byte 0xde, 0xa8	; LD IZ, 0

SeqName_SendSlotLoop:
	ld bc, iz
	ld wa, bc
	.byte 0xda, 0xa9	; LD DE, 1
	.byte 0x1e, 0x23, 0xff	; CALR LABEL_F919E3
	ld xde, xhl
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1C0000F
	call 0xFA9D58
	inc 1, iz
	cp iz, 0xA
	.byte 0x61, 0xe0	; JR LT, SeqName_SendSlotLoop

SeqName_ReturnZero:
	.byte 0xeb, 0xa8	; LD XHL, 0
	.byte 0x78, 0xeb, 0x01	; JRL T, SeqName_Exit

SeqName_HandleNavigation:
	ld wa, hl
	ld iz, hl
	or xde, xde
	.byte 0x6e, 0x33	; JR NZ, SeqName_HandlePlayAction
	.byte 0xc1, 0xfe, 0x84, 0x3f, 0x00	; CP (84FEh), 000h
	.byte 0x6e, 0x2c	; JR NZ, SeqName_HandlePlayAction
	cp xbc, 0x1C00018
	.byte 0x6e, 0x0b	; JR NZ, SeqName_CheckPrevKey
	cp wa, 0x9
	.byte 0x7f, 0x2d, 0x01	; JRL NC, SeqName_GetCurrentIndex
	inc 1, wa
	.byte 0x68, 0x10	; JR T, SeqName_UpdateIndex

SeqName_CheckPrevKey:
	cp xbc, 0x1C00017
	.byte 0x7e, 0x20, 0x01	; JRL NZ, SeqName_GetCurrentIndex
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x76, 0x1b, 0x01	; JRL Z, SeqName_GetCurrentIndex
	dec 1, wa

SeqName_UpdateIndex:
	.byte 0xf1, 0xd8, 0x82, 0x50	; LD (82D8h), WA
	ld de, wa
	.byte 0x78, 0x14, 0x01	; JRL T, SeqName_UpdateDisplay

SeqName_HandlePlayAction:
	cp xde, 0x4
	.byte 0x7e, 0xad, 0x00	; JRL NZ, SeqName_HandleAction32
	.byte 0xc1, 0xfe, 0x84, 0x3f, 0x00	; CP (84FEh), 000h
	.byte 0x7e, 0xa5, 0x00	; JRL NZ, SeqName_HandleAction32
	call LABEL_F941E5
	.byte 0xcf, 0xd8	; CP L, 0
	.byte 0x66, 0x1a	; JR Z, SeqName_CheckDiskAvail
	.byte 0xf1, 0x0c, 0x8a, 0x30	; LDA XWA, 8A0Ch
	.byte 0xb8, 0x01, 0xcf	; BIT 7, (XWA + 001h)
	.byte 0x6e, 0x11	; JR NZ, SeqName_CheckDiskAvail
	.byte 0xb0, 0x00, 0x01	; LD (XWA), 001h
	.byte 0xea, 0xa9	; LD XDE, 1
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C50004
	.byte 0x68, 0x2c	; JR T, SeqName_PostAndExit

SeqName_CheckDiskAvail:
	call 0xF8943E
	.byte 0xdb, 0xd8	; CP HL, 0
	.byte 0x66, 0x2b	; JR Z, SeqName_LoadAndPlay
	.byte 0xc2, 0xea, 0x40, 0x03, 0x3f, 0x00	; CP (0340EAh), 000h
	.byte 0x66, 0x23	; JR Z, SeqName_LoadAndPlay
	ld xwa, 0xFFFFFFFF
	ld xbc, 0x1C50000
	.byte 0xea, 0xa9	; LD XDE, 1
	call 0xFA9D58
	ld xwa, 0x600037
	ld xbc, 0x1C00001
	.byte 0xea, 0xa8	; LD XDE, 0

SeqName_PostAndExit:
	call 0xFA9D58
	.byte 0x78, 0xaa, 0x00	; JRL T, SeqName_GetCurrentIndex

SeqName_LoadAndPlay:
	ld xwa, 0x600026
	ld xbc, 0x1C00001
	.byte 0xea, 0xad	; LD XDE, 5
	call 0xFA9D58
	.byte 0xd8, 0xa8	; LD WA, 0
	.byte 0x1e, 0x72, 0x96	; CALR InitializeOperationState
	.byte 0xd1, 0xd8, 0x82, 0x20	; LD WA, (82D8h)
	call LABEL_F880AD
	ld wa, hl
	.byte 0xd9, 0xad	; LD BC, 5
	.byte 0x1e, 0xed, 0x98	; CALR LABEL_F8B48E
	.byte 0xf1, 0x42, 0x7f, 0x47	; LD (7F42h), L
	call LABEL_F89568
	call 0xF8953B
	call 0xF8987D
	.byte 0xf1, 0x02, 0x85, 0x53	; LD (8502h), HL
	.byte 0x1e, 0xa8, 0x96	; CALR SignalProgressUpdate
	ld xwa, 0x600026
	ld xbc, 0x1C00002
	.byte 0xea, 0xa8	; LD XDE, 0
	call 0xFA9D58
	.byte 0x30, 0xee, 0x00	; LD WA, 00eeh
	.byte 0x68, 0x56	; JR T, SeqName_ShowAndExit

SeqName_HandleAction32:
	cp xde, 0x32
	.byte 0x6e, 0x52	; JR NZ, SeqName_GetCurrentIndex
	ld xwa, 0x600026
	ld xbc, 0x1C00001
	.byte 0xea, 0xad	; LD XDE, 5
	call 0xFA9D58
	.byte 0xd8, 0xa8	; LD WA, 0
	.byte 0x1e, 0x1a, 0x96	; CALR InitializeOperationState
	.byte 0xd1, 0xd8, 0x82, 0x20	; LD WA, (82D8h)
	call LABEL_F880AD
	ld wa, hl
	.byte 0xd9, 0xad	; LD BC, 5
	.byte 0x1e, 0x95, 0x98	; CALR LABEL_F8B48E
	.byte 0xf1, 0x42, 0x7f, 0x47	; LD (7F42h), L
	call LABEL_F89568
	call 0xF8953B
	call 0xF8987D
	.byte 0xf1, 0x02, 0x85, 0x53	; LD (8502h), HL
	.byte 0x1e, 0x50, 0x96	; CALR SignalProgressUpdate
	ld xwa, 0x600026
	ld xbc, 0x1C00002
	.byte 0xea, 0xa8	; LD XDE, 0
	call 0xFA9D58
	.byte 0x30, 0xee, 0x00	; LD WA, 00eeh

SeqName_ShowAndExit:
	call LABEL_F994BD

SeqName_GetCurrentIndex:
	.byte 0xd1, 0xd8, 0x82, 0x22	; LD DE, (82D8h)

SeqName_UpdateDisplay:
	cp iz, de
	.byte 0x76, 0xa7, 0xfe	; JRL Z, SeqName_ReturnZero
	extz xde
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1E50002
	call 0xFA9D58
	ld wa, iz
	ld bc, iz
	.byte 0xda, 0xa9	; LD DE, 1
	.byte 0x1e, 0x9b, 0xfd	; CALR LABEL_F919E3
	ld xde, xhl
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1C0000F
	call 0xFA9D58
	.byte 0xd1, 0xd8, 0x82, 0x21	; LD BC, (82D8h)
	ld wa, bc
	.byte 0xda, 0xa9	; LD DE, 1
	.byte 0x1e, 0x81, 0xfd	; CALR LABEL_F919E3
	ld xde, xhl
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1C0000F
	.byte 0x68, 0x4b	; JR T, SeqName_PostEventExit

SeqName_SetIndexPlaying:
	.byte 0xc1, 0xfe, 0x84, 0x3f, 0x00	; CP (84FEh), 000h
	.byte 0x76, 0x60, 0xfe	; JRL Z, SeqName_ReturnZero
	ld iz, hl
	.byte 0xf1, 0xd8, 0x82, 0x52	; LD (82D8h), DE
	extz xde
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1E50002
	call 0xFA9D58
	ld wa, iz
	ld bc, iz
	.byte 0xda, 0xa9	; LD DE, 1
	.byte 0x1e, 0x4e, 0xfd	; CALR LABEL_F919E3
	ld xde, xhl
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
	ld xbc, 0x1C0000F
	call 0xFA9D58
	.byte 0xd1, 0xd8, 0x82, 0x21	; LD BC, (82D8h)
	ld wa, bc
	.byte 0xda, 0xa9	; LD DE, 1
	.byte 0x1e, 0x34, 0xfd	; CALR LABEL_F919E3
	ld xde, xhl
	.byte 0xe1, 0xd4, 0x82, 0x20	; LD XWA, (82D4h)
