FormatMedleyNumber:
	.byte 0xf5, 0xe0, 0x45	; LD (XWA+), E
	cp c, 0xFF
	.byte 0x6e, 0x04	; JR NZ, FmtNum_CheckMarked
	.byte 0x23, 0x20	; LD_C 020h
	.byte 0x68, 0x07	; JR T, FmtNum_WriteSpacePad

FmtNum_CheckMarked:
	cp c, 0xFE
	.byte 0x6e, 0x0d	; JR NZ, FmtNum_FormatNumber
	.byte 0x23, 0x4d	; LD_C 04dh

FmtNum_WriteSpacePad:
	.byte 0xf5, 0xe0, 0x43	; LD (XWA+), C
	.byte 0xf5, 0xe0, 0x00, 0x20	; LD (XWA+), 020h
	.byte 0xb0, 0x00, 0x20	; LD (XWA), 020h
	ret

FmtNum_FormatNumber:
	inc 1, c
	cp c, 0x64
	.byte 0x67, 0x18	; JR C, FmtNum_WriteM
	.byte 0xf5, 0xe0, 0x33	; LDA_XHL_XWA_plus__e0__
	ld e, c
	extz de
	.byte 0xcd, 0x0a, 0x64	; DIV_E 064h
	add e, 0x30
	ld (xhl), e
	extz bc
	.byte 0xcb, 0x0a, 0x64	; DIV_C 064h
	ld c, b
	.byte 0x68, 0x04	; JR T, FmtNum_WriteTensUnits

FmtNum_WriteM:
	.byte 0xf5, 0xe0, 0x00, 0x4d	; LD (XWA+), 04dh

FmtNum_WriteTensUnits:
	cp c, 0xA
	.byte 0x6f, 0x0a	; JR NC, FmtNum_WriteTwoDigits
	.byte 0xf5, 0xe0, 0x00, 0x30	; LD (XWA+), 030h
	add c, 0x30
	ld (xwa), c
	ret

FmtNum_WriteTwoDigits:
	.byte 0xf5, 0xe0, 0x33	; LDA_XHL_XWA_plus__e0__
	ld e, c
	extz de
	.byte 0xcd, 0x0a, 0x0a	; DIV_E 00ah
	add e, 0x30
	ld (xhl), e
	extz bc
	.byte 0xcb, 0x0a, 0x0a	; DIV_C 00ah
	ld c, b
	add c, 0x30
	ld (xwa), c
	ret

