Reset_Floppy_Disk_Controller:	; F97EC9
; I am not entirely sure yet, but it looks like FDC initialization code...

	; reset FDC by toggling Port D bit 0
	.byte 0xf0, 0x34, 0xb8	; SET 0, (PD)
	.byte 0x30, 0x0a, 0x00	; LD WA, 000ah
	.byte 0x1e, 0x40, 0xf7	; CALR SOME_DELAY
	.byte 0xf0, 0x34, 0xb0	; RES 0, (PD)
	.byte 0x30, 0x0a, 0x00	; LD WA, 000ah
	.byte 0x78, 0x37, 0xf7	; JRL T, SOME_DELAY

	; then do a lot of other stuff I still don't undertsand:

	.byte 0x08, 0x47, 0x1e	; LD (PHFC), 01eh
	.byte 0xf0, 0x34, 0xce	; BIT 6, (PD)	; Port D bit 6: "FD.I/O signal"
	.byte 0xb0, 0xfe	; RET NZ
