	.byte 0xf0, 0x34, 0xce	; BIT 6, (PD)
	.byte 0x66, 0x03	; JR Z, Detected_Floppy_Disk_Change
	.byte 0x27, 0x00	; LD_L 000h
	ret

Detected_Floppy_Disk_Change:	; F98009
