; Control Panel routines moved to cpanel_routines.asm
; --- begin include: cpanel_routines.asm ---
; =============================================================================
; cpanel_routines.asm - Control Panel Communication Routines
; =============================================================================
; This file contains all control panel communication routines for the KN5000
; Main CPU. The control panel consists of two MCUs (left and right panels)
; that communicate with the main CPU via serial protocol.
;
; Routines included:
;   Initialization:
;     CPanel_InitHardware       - Initialize serial port and buffers
;     CPanel_SendInitSequence   - Send initialization sequence to panels
;     CPanel_InitLEDBuffer      - Initialize LED TX buffer
;     CPanel_InitButtonState    - Initialize button state arrays
;
;   Button Handling:
;     CPanel_ScanButtons        - Main button scan entry point
;     CPanel_ReadAllButtons     - Read button states from both panels
;     CPanel_CheckSpecialCombos - Check for special button combinations
;     CPanel_PollStartup        - Poll buttons during startup
;     CPanel_ButtonPollLoop     - Button polling loop
;     CPanel_EncoderCheck       - Check encoder state
;
;   Serial Communication:
;     CPanel_WaitTXReady        - Wait for TX ready
;     CPanel_SendCommand        - Send command to panel
;
;   State Machine:
;     CPANEL_STATE_MACHINE_TABLE - State machine jump table
;     CPanel_SM_StartTX         - Start TX state
;     CPanel_SM_TXDelay1/2      - TX delay states
;     CPanel_SM_SendByte1/N     - Send byte states
;     CPanel_SM_TXComplete      - TX complete state
;     CPanel_SM_RXByte1/N       - Receive byte states
;     CPanel_SM_Idle            - Idle state
;
;   Packet Processing:
;     CPanel_RX_ProcessWithFlag - Process RX with flag
;     CPanel_RX_Process         - Main RX processing
;     CPanel_RX_ParseNext       - Parse next packet
;     CPanel_RX_PacketHandlers  - Packet type dispatch table
;     CPanel_RX_ButtonPacket    - Handle button packets
;     CPanel_RX_EncoderPacket   - Handle encoder packets
;     CPanel_RX_MultiBytePacket - Handle multi-byte packets
;     CPanel_RX_SyncPacket      - Handle sync packets
;
;   LED Control:
;     CPanel_UpdateLEDs         - Update LED states
;     CPanel_LED_PacketHandlers - LED packet dispatch table
;
;   Buffer Management:
;     CPanel_IncRXPtr           - Increment RX buffer pointer
;     CPanel_IncLEDPtr          - Increment LED buffer pointer
;     CPanel_IncEventPtr        - Increment event queue pointer
;     CPanel_DecEventPtr        - Decrement event queue pointer
;
; Required includes before this file:
;   - cpanel_constants.asm (or equivalent EQU definitions)
;
; =============================================================================

CPanel_ScanButtons:	; FC3EE5
	push xix
	push xiz
	push xhl
	push xde
	call 0xFC41FC
	pop xde
	pop xhl
	pop xiz
	pop xix
	.byte 0x1e, 0x71, 0x02	; CALR CPanel_CheckSpecialCombos
	ret


CPanel_InitHardware:
	.byte 0x43, 0xad, 0x00, 0x02, 0x00	; LD XHL, CPANEL_RX_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h

	.byte 0x43, 0x37, 0x01, 0x02, 0x00	; LD XHL, CPANEL_LED_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h

	.byte 0x21, 0x03	; LD_A 003h	; PF2=SCK0 Disabled, PF0=TxD0 and PF1=RXD0 (MIDI)
	and a, 0xAF	; PF6=SCK1 Disabled, PF4=TxD1 and PF5=RXD1 (Control Panel)
	.byte 0xf1, 0x8f, 0x8d, 0x41	; LD (PFFC_VALUE), A
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	.byte 0x21, 0x15	; LD_A 015h
	and a, 0x8F
	.byte 0xf1, 0x8e, 0x8d, 0x41	; LD (PFCR_VALUE), A
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0xc0, 0x3c, 0x3c, 0xbf	; AND (PF), 0bfh	; PF bit 6, (SCLK1 | /CTS1) = 0
	.byte 0x21, 0x00	; LD_A 000h
	.byte 0xf0, 0x3b, 0x41	; LD (PEFC), A
	.byte 0x21, 0x46	; LD_A 046h
	.byte 0xf0, 0x3a, 0x41	; LD (PECR), A
	.byte 0x08, 0xd6, 0x00	; LD (SC1MOD), 000h	; serial clk: TO2 trigger
	                  ; serial transfer mode: I/O  transfer mode
	                  ; wake-up function: disable
	                  ; receive control: receive disable
	                  ; handshake function control: CTS disable
	.byte 0x08, 0xd7, 0x14	; LD (BR1CR), 014h	; Internal Clock T2 (16/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/16/4 = 250kHz
	.byte 0x08, 0xd5, 0x01	; LD (SC1CR), 001h	; Parity: odd
	                 ; Parity addition: disable
	                 ; clear all errors
	                 ; Data transmit/receive at SCLK1 rising edge
	                 ; I/O interface input clock: SCLK1 pin input
	.byte 0x08, 0xe3, 0x07	; LD (INTEAB), 007h
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xeb, 0xff	; LD (INTES1), 0ffh
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	.byte 0xc0, 0xc8, 0x3e, 0x10	; OR (TAMOD), 010h
	.byte 0xc0, 0xc8, 0x3c, 0xf7	; AND (TAMOD), 0f7h
	.byte 0xf1, 0x91, 0x8d, 0x00, 0x7d	; LD (CPANEL_UNUSED_1), 07dh	; This looks pointless...

	.byte 0xc1, 0x8c, 0x8d, 0x3e, 0x40	; OR (CPANEL_TX_RX_FLAGS), 040h	; CP_Flags_A.6 = 1
	.byte 0xf1, 0x8b, 0x8d, 0x00, 0x00	; LD (CPANEL_PACKET_BYTE_COUNT), 000h
	.byte 0xc1, 0x8c, 0x8d, 0x3c, 0xfc	; AND (CPANEL_TX_RX_FLAGS), 0fch	; CP_Flags_A.10 = 00
	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0xf1, 0xff, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_WRITE_PTR), 0000h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h

	.byte 0x1e, 0xa7, 0x01	; CALR DELAY_6_TICKS

	.byte 0x21, 0x1f	; LD_A 01fh
	.byte 0x20, 0xda	; LD_W 0dah
	.byte 0x1e, 0x2e, 0x04	; CALR CPanel_SendCommand
	.byte 0x1e, 0x7c, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0x1e, 0x73, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0x1e, 0x01, 0x00	; CALR CPanel_SendInitSequence
	ret


; CPanel_SendInitSequence - Send initialization command sequence to control panel MCUs
; Commands sent: 0x1F 0x1A, 0x1D 0x00, 0xDD 0x03, 0x1E 0x80
CPanel_SendInitSequence:
	.byte 0x21, 0x1f	; LD_A 01fh
	.byte 0x20, 0x1a	; LD_W 01ah
	.byte 0x1e, 0x17, 0x04	; CALR CPanel_SendCommand
	.byte 0x1e, 0x65, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0x1e, 0x5c, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0x21, 0x1d	; LD_A 01dh
	.byte 0x20, 0x00	; LD_W 0
	.byte 0x1e, 0x04, 0x04	; CALR CPanel_SendCommand
	.byte 0x1e, 0x52, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0x1e, 0x49, 0x01	; CALR DELAY_3000_LOOPS
	.byte 0x1e, 0x46, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0x21, 0xdd	; LD_A 0ddh
	.byte 0x20, 0x03	; LD_W 03h
	.byte 0x1e, 0xee, 0x03	; CALR CPanel_SendCommand
	.byte 0x1e, 0x3c, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0x1e, 0x33, 0x01	; CALR DELAY_3000_LOOPS
	.byte 0x1e, 0x30, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0x21, 0x1e	; LD_A 01eh
	.byte 0x20, 0x80	; LD_W 080h
	.byte 0x1e, 0xd8, 0x03	; CALR CPanel_SendCommand
	.byte 0x1e, 0x26, 0x01	; CALR DELAY_3000_LOOPS
	.byte 0x1e, 0x23, 0x01	; CALR DELAY_3000_LOOPS
	.byte 0x1e, 0x20, 0x01	; CALR DELAY_3000_LOOPS

	.byte 0x06, 0x06	; EI 006h
	.byte 0x08, 0xeb, 0xff	; LD (INTES1), 0ffh
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	.byte 0xc0, 0xd6, 0x3c, 0xdf	; AND (SC1MOD), 0dfh	; RXE (bit 5) = 0: receive disable
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xe3, 0x05	; LD (INTEAB), 005h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h
	ret


CPanel_InitLEDBuffer:
	.byte 0xf1, 0x01, 0x8e, 0x50	; LD (CPANEL_LED_TX_BUFFER), WA
	.byte 0xc1, 0x8f, 0x8d, 0x3c, 0xbf	; AND (PFFC_VALUE), 0bfh
	.byte 0xc1, 0x8f, 0x8d, 0x21	; LD A,(PFFC_VALUE)
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	.byte 0x08, 0xeb, 0xff	; LD (0ebh), 0ffh
	.byte 0x08, 0xf8, 0x22	; LD (0f8h), 022h
	.byte 0x08, 0xf8, 0x23	; LD (0f8h), 023h
	.byte 0x08, 0xe3, 0x07	; LD (0e3h), 007h
	.byte 0x08, 0xf8, 0x12	; LD (0f8h), 012h
	.byte 0xc0, 0x3c, 0x3c, 0xbf	; AND (03ch), 0bfh
	.byte 0xc1, 0x8e, 0x8d, 0x3e, 0x40	; OR (PFCR_VALUE), 040h
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A,(PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0x1e, 0xad, 0x00	; CALR DELAY_300_LOOPS
	.byte 0x1e, 0xaa, 0x00	; CALR DELAY_300_LOOPS
	.byte 0xc1, 0x8e, 0x8d, 0x3c, 0xbf	; AND (PFCR_VALUE), 0bfh
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A,(PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0x1e, 0x9b, 0x00	; CALR DELAY_300_LOOPS
	.byte 0x1e, 0x98, 0x00	; CALR DELAY_300_LOOPS
	.byte 0xc1, 0x8f, 0x8d, 0x3e, 0x50	; OR (PFFC_VALUE), 050h
	.byte 0xc1, 0x8f, 0x8d, 0x21	; LD A, (PFFC_VALUE)
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	.byte 0xc1, 0x8e, 0x8d, 0x3e, 0x50	; OR (PFCR_VALUE), 050h
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0xc0, 0xd5, 0x3c, 0xfe	; AND (SC1CR), 0feh
	.byte 0x08, 0xeb, 0xff	; LD (0ebh), 0ffh
	.byte 0x08, 0xf8, 0x22	; LD (0f8h), 022h
	.byte 0x08, 0xf8, 0x23	; LD (0f8h), 023h
	.byte 0x45, 0x01, 0x8e, 0x00, 0x00	; LD XIY, CPANEL_LED_TX_BUFFER
	.byte 0xd1, 0xfd, 0x8d, 0x85	; ADD IY, (CPANEL_LED_READ_PTR)
	ld a, (xiy)
	.byte 0xd1, 0xfd, 0x8d, 0x61	; INCW 1, (CPANEL_LED_READ_PTR)
	.byte 0xf0, 0xd4, 0x41	; LD (SC1BUF), A
	.byte 0x1e, 0x5e, 0x00	; CALR DELAY_300_LOOPS
	.byte 0x1e, 0x5b, 0x00	; CALR DELAY_300_LOOPS
	.byte 0x45, 0x01, 0x8e, 0x00, 0x00	; LD XIY, CPANEL_LED_TX_BUFFER
	.byte 0xd1, 0xfd, 0x8d, 0x85	; ADD IY, (CPANEL_LED_READ_PTR)
	ld a, (xiy)
	.byte 0xd1, 0xfd, 0x8d, 0x61	; INCW 1, (CPANEL_LED_READ_PTR)
	.byte 0xf0, 0xd4, 0x41	; LD (SC1BUF), A
	.byte 0x1e, 0x46, 0x00	; CALR DELAY_300_LOOPS
	.byte 0x1e, 0x43, 0x00	; CALR DELAY_300_LOOPS
	.byte 0xc0, 0xd5, 0x3e, 0x01	; OR (SC1CR), 001h
	.byte 0xc0, 0xd5, 0x3c, 0xfd	; AND (SC1CR), 0fdh
	.byte 0xc1, 0x8e, 0x8d, 0x3c, 0xaf	; AND (PFCR_VALUE), 0afh
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0xc1, 0x8f, 0x8d, 0x3c, 0xaf	; AND (PFFC_VALUE), 0afh
	.byte 0xc1, 0x8f, 0x8d, 0x21	; LD A, (PFFC_VALUE)
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	ret



; Below are routines that loop N times, where
; N = 2, 6, 10, 300, 1500 or 3000
; These are likely pauses
; But these values are also suspiciously similar to proportions
; between typical baudrates, but this is just a hunch for now...

LABEL_FC0DE:
	.byte 0xd8, 0xaa	; LD WA, 2

LABEL_FC40E0:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC40E8
	.byte 0x68, 0xf8	; JR T, LABEL_FC40E0

LABEL_FC40E8:
	ret


Delay_6_Loops:
	.byte 0xd8, 0xae	; LD WA, 6

LABEL_FC40EB:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC40F3
	.byte 0x68, 0xf8	; JR T, LABEL_FC40EB

LABEL_FC40F3:
	ret


DELAY_10_LOOPS:	; FC40F4
	.byte 0x30, 0x0a, 0x00	; LD WA, 000ah

LABEL_FC40F7:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC40FF
	.byte 0x68, 0xf8	; JR T, LABEL_FC40F7

LABEL_FC40FF:
	ret


DELAY_300_LOOPS:	; FC4100
	.byte 0x30, 0x2c, 0x01	; LD WA, 012ch

LABEL_FC4103:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC410B
	.byte 0x68, 0xf8	; JR T, LABEL_FC4103

LABEL_FC410B:
	ret


DELAY_1500_LOOPS:	; FC410C
	.byte 0x30, 0xdc, 0x05	; LD WA, 05dch

LABEL_FC410F:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC4117
	.byte 0x68, 0xf8	; JR T, LABEL_FC410F

LABEL_FC4117:
	ret


DELAY_3000_LOOPS:	; FC4118
	.byte 0x30, 0xb8, 0x0b	; LD WA, 0bb8h

LABEL_FC411B:
	dec 1, wa
	.byte 0xd8, 0xd8	; CP WA, 0
	.byte 0x66, 0x02	; JR Z, LABEL_FC4123
	.byte 0x68, 0xf8	; JR T, LABEL_FC411B

LABEL_FC4123:
	ret


LABEL_FC4124:
	.byte 0xd1, 0x09, 0x04, 0x20, 0xf1, 0x9b, 0x8d, 0x50
	.byte 0xd1, 0x09, 0x04, 0x20, 0xd1, 0x9b, 0x8d, 0xa0
	.byte 0xd8, 0xda, 0x61, 0xf4, 0x0e


DELAY_6_TICKS:
	.byte 0xd1, 0x09, 0x04, 0x20	; LD WA, (SYSTEM_TIMESTAMP)
	.byte 0xf1, 0x9b, 0x8d, 0x50	; LD (TIMESTAMP_FOR_DELAY), WA

LABEL_FC4141:
	.byte 0xd1, 0x09, 0x04, 0x20	; LD WA, (SYSTEM_TIMESTAMP)
	.byte 0xd1, 0x9b, 0x8d, 0xa0	; SUB WA, (TIMESTAMP_FOR_DELAY)
	.byte 0xd8, 0xde	; CP WA, 6
	.byte 0x61, 0xf4	; JR LT, LABEL_FC4141
	ret


DELAY_51_TICKS:
	.byte 0xd1, 0x09, 0x04, 0x20	; LD WA, (SYSTEM_TIMESTAMP)
	.byte 0xf1, 0x9b, 0x8d, 0x50	; LD (TIMESTAMP_FOR_DELAY), WA

LABEL_FC4156:
	.byte 0xd1, 0x09, 0x04, 0x20	; LD WA, (SYSTEM_TIMESTAMP)
	.byte 0xd1, 0x9b, 0x8d, 0xa0	; SUB WA, (TIMESTAMP_FOR_DELAY)
	cp wa, 0x33
	.byte 0x61, 0xf2	; JR LT, LABEL_FC4156
	ret

; ???? R        L
; ???? 25 (001 00101): 01 | e2 (111 00010): 04
; ???? 20 (001 00000): 10 | e2 (111 00010): 11

CPanel_CheckSpecialCombos:
	.byte 0xc1, 0x5e, 0x8e, 0x3f, 0x6c	; CP (STATE_OF_CPANEL_BUTTONS_LEFT + 4), 06ch	;  CPL_SEG4 = 0110 1100 = AUTO PLAY CHORD + SPLIT POINT + VARIATION 4 + VARIATION 3 => display sw internal build numbers
	.byte 0x6e, 0x04	; JR NZ, CPanel_SpecialCombo_FirmwareVersion
	.byte 0xdb, 0xab	; LD HL, 3	; SOFT VERSION SCREEN
	.byte 0x68, 0x23	; JR T, LABEL_FC4193

CPanel_SpecialCombo_FirmwareVersion:
	.byte 0xc1, 0x4b, 0x8e, 0x3f, 0x70	; CP (STATE_OF_CPANEL_BUTTONS_RIGHT + 1), 070h	; CPR_SEG1 = 0111 0000 = GM SPECIAL + ACCORDION REGISTER + DIGITAL DRAWBAR => display fw version on screen & LEDs
	.byte 0x6e, 0x04	; JR NZ, CPanel_SpecialCombo_SoftVersion
	.byte 0xdb, 0xaa	; LD HL, 2
	.byte 0x68, 0x18	; JR T, LABEL_FC4193

CPanel_SpecialCombo_SoftVersion:
	.byte 0xc1, 0x60, 0x8e, 0x3f, 0x38	; CP (STATE_OF_CPANEL_BUTTONS_LEFT + 6), 038h	; CPL_SEG6 = 0011 1000 = SHOWTIME & TRAD DANCE + PARTY TIME + MARCH & WALTZ => ?
	.byte 0x6e, 0x04	; JR NZ, CPanel_SpecialCombo_BuildInfo
	.byte 0xdb, 0xa9	; LD HL, 1
	.byte 0x68, 0x0d	; JR T, LABEL_FC4193

CPanel_SpecialCombo_BuildInfo:
	.byte 0xc1, 0x50, 0x8e, 0x3f, 0x0f	; CP (STATE_OF_CPANEL_BUTTONS_RIGHT + 6), 00fh	; CPR_SEG6 = 0000 1111 = 4 panel memory buttons (PM 4 + PM 3 + PM 2 + PM 1) => fw update
	.byte 0x6e, 0x04	; JR NZ, CPanel_SpecialCombo_FirmwareUpdate
	.byte 0xdb, 0xac	; LD HL, 4
	.byte 0x68, 0x02	; JR T, LABEL_FC4193

CPanel_SpecialCombo_FirmwareUpdate:
	.byte 0xdb, 0xa8	; LD HL, 0

LABEL_FC4193:
	ret


CPanel_PanelDetection:
	.byte 0xf1, 0x93, 0x8d, 0x00, 0x00	; LD (CPANEL_PANEL_DETECT_FLAGS), 000h
	.byte 0x1e, 0xd9, 0x01	; CALR CPanel_WaitTXReady
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h
	.byte 0x21, 0x20	; LD_A 020h	; my guess: 20 = 001 00000 where 001 = left-panel mcu
	.byte 0x20, 0x00	; LD_W 0
	.byte 0x1e, 0x0f, 0x02	; CALR CPanel_SendCommand
	.byte 0x1e, 0x7e, 0xff	; CALR DELAY_6_TICKS
	.byte 0xd1, 0x9f, 0x8d, 0x3f, 0x00, 0x00	; CPW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0x66, 0x05	; JR Z, LABEL_FC41C8
	.byte 0xc1, 0x93, 0x8d, 0x3e, 0x01	; OR (CPANEL_PANEL_DETECT_FLAGS), 001h	; my guess: CP_Flags_C.0
					  ; = Got response from left-panel MCU

LABEL_FC41C8:
	.byte 0x1e, 0xaa, 0x01	; CALR CPanel_WaitTXReady
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h
	.byte 0x21, 0xe0	; LD_A 0e0h	; my guess: E0 = 111 00000 where 111 = right-panel mcu
	.byte 0x20, 0x00	; LD_W 0
	.byte 0x1e, 0xe0, 0x01	; CALR CPanel_SendCommand
	.byte 0x1e, 0x4f, 0xff	; CALR DELAY_6_TICKS
	.byte 0xd1, 0x9f, 0x8d, 0x3f, 0x00, 0x00	; CPW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0x66, 0x05	; JR Z, LABEL_FC41F7
	.byte 0xc1, 0x93, 0x8d, 0x3e, 0x08	; OR (CPANEL_PANEL_DETECT_FLAGS), 008h	; my guess: CP_Flags_C.4
					 ; = Got response from right-panel MCU

LABEL_FC41F7:
	.byte 0xc1, 0x93, 0x8d, 0x21	; LD A, (CPANEL_PANEL_DETECT_FLAGS)
	ret


CPanel_ReadAllButtons:
	.byte 0x43, 0xad, 0x00, 0x02, 0x00	; LD XHL, CPANEL_RX_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h

	.byte 0x06, 0x06	; EI 006h
	.byte 0xd1, 0x9d, 0x8d, 0x20	; LD WA, (CPANEL_RX_READ_PTR)
	.byte 0xf1, 0x9f, 0x8d, 0x50	; LD (CPANEL_RX_WRITE_PTR), WA
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h

	call 0xFC4375
	.byte 0x21, 0x25	; LD_A 025h
	.byte 0x20, 0x01	; LD_W 01h
	call 0xFC43C7
	.byte 0x1e, 0x09, 0xff	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x06, 0xff	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x03, 0xff	; CALR DELAY_6_TICKS

	.byte 0x1e, 0x3c, 0x01	; CALR CPanel_WaitTXReady
	.byte 0x21, 0xe2	; LD_A 0e2h
	.byte 0x20, 0x04	; LD_W 04h
	.byte 0x1e, 0x87, 0x01	; CALR CPanel_SendCommand
	.byte 0x1e, 0xf6, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xf3, 0xfe	; CALR DELAY_6_TICKS

	.byte 0x1e, 0x2c, 0x01	; CALR CPanel_WaitTXReady
	.byte 0x21, 0x20	; LD_A 020h
	.byte 0x20, 0x10	; LD_W 010h
	.byte 0x1e, 0x77, 0x01	; CALR CPanel_SendCommand
	.byte 0x1e, 0xe6, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xe3, 0xfe	; CALR DELAY_6_TICKS

	.byte 0x1e, 0x1c, 0x01	; CALR CPanel_WaitTXReady
	.byte 0x21, 0xe2	; LD_A 0e2h
	.byte 0x20, 0x11	; LD_W 011h
	.byte 0x1e, 0x67, 0x01	; CALR CPanel_SendCommand
	.byte 0x1e, 0xd6, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xd3, 0xfe	; CALR DELAY_6_TICKS

	.byte 0x1e, 0xac, 0x06	; CALR CPanel_RX_Process
	ret


CPanel_PollStartup:
	.byte 0x43, 0xad, 0x00, 0x02, 0x00	; LD XHL, CPANEL_RX_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h

CPanel_ButtonPollLoop:
	.byte 0x1e, 0xdf, 0x00	; CALR CPanel_WaitTXReady
	.byte 0x21, 0x20	; LD_A 020h
	.byte 0x20, 0x0b	; LD_W 0bh
	.byte 0x1e, 0x2a, 0x01	; CALR CPanel_SendCommand
	.byte 0x1e, 0x99, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x72, 0x06	; CALR CPanel_RX_Process

	.byte 0xc1, 0x55, 0x8e, 0x21	; LD A, (STATE_OF_CPANEL_BUTTONS + 11)	; Byte 11 is in gap between CPR (0-10) and CPL (16-26), possibly status/mode
	.byte 0x20, 0x0d	; LD_W 0dh	; Default encoder check mode
	.byte 0xc9, 0x33, 0x07	; BIT 7, A	; Test bit 7 of status byte
	.byte 0x6e, 0x09	; JR NZ, CPanel_EncoderCheck
	.byte 0x20, 0x0e	; LD_W 0eh	; Alternate mode if bit 7 set
	.byte 0xc9, 0x33, 0x06	; BIT 6, A	; Test bit 6 of status byte
	.byte 0x6e, 0x02	; JR NZ, CPanel_EncoderCheck
	.byte 0x20, 0x0c	; LD_W 0ch	; Third mode if bit 6 set

CPanel_EncoderCheck:
	.byte 0xc1, 0x6a, 0x8e, 0xf8	; CP (8E6Ah), W
	.byte 0xf1, 0x6a, 0x8e, 0x40	; LD (8E6Ah), W
	.byte 0x6e, 0xd2	; JR NZ, CPanel_ButtonPollLoop
	.byte 0xf1, 0x6a, 0x8e, 0x40	; LD (8E6Ah), W
	.byte 0x43, 0xad, 0x00, 0x02, 0x00	; LD XHL, CPANEL_RX_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0xf1, 0xff, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_WRITE_PTR), 0000h
	.byte 0xf1, 0x9d, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_READ_PTR), 0000h
	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h
	ret


CPanel_InitButtonState:	; do that
	.byte 0x43, 0xad, 0x00, 0x02, 0x00	; LD XHL, CPANEL_RX_EVENT_QUEUE
	.byte 0xbb, 0xfc, 0x02, 0x00, 0x00	; LDW (XHL - 4), 0000h
	.byte 0xbb, 0xf8, 0x02, 0x00, 0x00	; LDW (XHL - 8), 0000h
	.byte 0xbb, 0xfe, 0x02, 0x80, 0x00	; LDW (XHL - 2), 0080h

	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0x9d, 0x8d, 0x00, 0x00	; LD (CPANEL_RX_READ_PTR), 000h
	.byte 0xf1, 0x9f, 0x8d, 0x00, 0x00	; LD (CPANEL_RX_WRITE_PTR), 000h
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x01	; OR (CPANEL_PROTOCOL_FLAGS), 001h	; CP_Flags_B.0 = 1
	.byte 0x06, 0x00	; EI 000h

	.byte 0x1e, 0x50, 0x00	; CALR CPanel_WaitTXReady
	.byte 0x21, 0x2b	; LD_A 02bh
	.byte 0x20, 0x00	; LD_W 0
	.byte 0x1e, 0x9b, 0x00	; CALR CPanel_SendCommand
	.byte 0x1e, 0x0a, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x07, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x04, 0xfe	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xd6, 0x05	; CALR CPanel_RX_ProcessWithFlag

	.byte 0x1e, 0x3a, 0x00	; CALR CPanel_WaitTXReady
	.byte 0x21, 0xeb	; LD_A 0ebh
	.byte 0x20, 0x00	; LD_W 0
	.byte 0x1e, 0x85, 0x00	; CALR CPanel_SendCommand
	.byte 0x1e, 0xf4, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xf1, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xee, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xc0, 0x05	; CALR CPanel_RX_ProcessWithFlag

	.byte 0x1e, 0x24, 0x00	; CALR CPanel_WaitTXReady
	.byte 0x21, 0x20	; LD_A 020h
	.byte 0x20, 0x10	; LD_W 010h
	.byte 0x1e, 0x6f, 0x00	; CALR CPanel_SendCommand
	.byte 0x1e, 0xde, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xdb, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xad, 0x05	; CALR CPanel_RX_ProcessWithFlag

	.byte 0x1e, 0x11, 0x00	; CALR CPanel_WaitTXReady
	.byte 0x21, 0xe3	; LD_A 0e3h
	.byte 0x20, 0x10	; LD_W 010h
	.byte 0x1e, 0x5c, 0x00	; CALR CPanel_SendCommand
	.byte 0x1e, 0xcb, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0xc8, 0xfd	; CALR DELAY_6_TICKS
	.byte 0x1e, 0x9a, 0x05	; CALR CPanel_RX_ProcessWithFlag
	ret


CPanel_WaitTXReady:
	.byte 0xf1, 0x97, 0x8d, 0x00, 0xc8	; LD (CPANEL_COUNTER_DOWN_FROM_200), 0c8h	; =200

CPanel_WaitTXReady_Poll:
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf0, 0x3c, 0xce	; BIT 6, (PF)	; PF.6 = state of SCLK1 pin == 1, (resting at pull-up)
	.byte 0x66, 0x13	; JR Z, CPanel_WaitTXReady_Timeout
	.byte 0xf0, 0x38, 0xcd	; BIT 5, (PE)	; PE.5 = state of INTA pin == 0
	.byte 0x6e, 0x0e	; JR NZ, CPanel_WaitTXReady_Timeout
	.byte 0xf1, 0x8c, 0x8d, 0xc9	; BIT 1, (CPANEL_TX_RX_FLAGS)
	.byte 0x6e, 0x08	; JR NZ, CPanel_WaitTXReady_Timeout
	.byte 0xf1, 0x8c, 0x8d, 0xc8	; BIT 0, (CPANEL_TX_RX_FLAGS)
	.byte 0x6e, 0x02	; JR NZ, CPanel_WaitTXReady_Timeout
	.byte 0x68, 0x12	; JR T, CPanel_WaitTXReady_BufferCheck

CPanel_WaitTXReady_Timeout:
	.byte 0xc1, 0x97, 0x8d, 0x69	; DEC 1, (CPANEL_COUNTER_DOWN_FROM_200)
	.byte 0xc1, 0x97, 0x8d, 0x3f, 0x00	; CP (CPANEL_COUNTER_DOWN_FROM_200), 000h
	.byte 0x66, 0x11	; JR Z, LABEL_FC43B0
	.byte 0x06, 0x00	; EI 000h
	.byte 0x1e, 0x68, 0xfd	; CALR DELAY_1500_LOOPS
	.byte 0x68, 0xd4	; JR T, CPanel_WaitTXReady_Poll

CPanel_WaitTXReady_BufferCheck:
	; Only reaches here when CP_Flags_A.10 == 00, and I think only CPanel_SM_Idle sets that value...

	.byte 0xd1, 0xff, 0x8d, 0x20	; LD WA, (CPANEL_LED_WRITE_PTR)
	.byte 0xd1, 0xfd, 0x8d, 0xf0	; CP WA, (CPANEL_LED_READ_PTR)
	.byte 0x6e, 0xe4	; JR NZ, CPanel_WaitTXReady_Timeout

LABEL_FC43B0:
	.byte 0x06, 0x06	; EI 006h
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	.byte 0x08, 0xeb, 0xdd	; LD (INTES1), 0ddh
	.byte 0xc0, 0xd6, 0x3c, 0xdf	; AND (SC1MOD), 0dfh	; RXE (bit 5) = 0: receive disable
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x80	; OR (CPANEL_PROTOCOL_FLAGS), 080h	; CP_Flags_B.7 = 1
	.byte 0x06, 0x00	; EI 000h
	ret


CPanel_SendCommand:
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf1, 0xfd, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_READ_PTR), 0000h
	.byte 0xf1, 0xff, 0x8d, 0x02, 0x00, 0x00	; LDW (CPANEL_LED_WRITE_PTR), 0000h
	.byte 0xf1, 0x01, 0x8e, 0x50	; LD (CPANEL_LED_TX_BUFFER), WA
	.byte 0xd1, 0xff, 0x8d, 0x38, 0x02, 0x00	; ADDW (CPANEL_LED_WRITE_PTR), 0002h
	.byte 0xc1, 0x8c, 0x8d, 0x3e, 0x02	; OR (CPANEL_TX_RX_FLAGS), 002h
	.byte 0xc1, 0x8c, 0x8d, 0x3c, 0xfe	; AND (CPANEL_TX_RX_FLAGS), 0feh	; CP_Flags_A.10 = 2
	.byte 0xf1, 0x8a, 0x8d, 0x00, 0x04	; LD (CPANEL_STATE_MACHINE_INDEX), 004h	; ROUTINE_1
	.byte 0x08, 0xd7, 0x28	; LD (BR1CR), 028h	; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	.byte 0xc1, 0x8f, 0x8d, 0x3c, 0xbf	; AND (PFFC_VALUE), 0bfh	; disable CPanel serial ckl
	.byte 0xc1, 0x8f, 0x8d, 0x21	; LD A, (PFFC_VALUE)
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	.byte 0xc0, 0x3c, 0x3c, 0xbf	; AND (PF), 0bfh	; PF bit 6: SCLK1 = 0
	.byte 0xc1, 0x8e, 0x8d, 0x3e, 0x40	; OR (PFCR_VALUE), 040h
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0x08, 0xe3, 0x07	; LD (INTEAB), 007h
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0xc0, 0xd6, 0x3c, 0xdf	; AND (SC1MOD), 0dfh	; RXE (bit 5) = 0: CPanel receive disable
	.byte 0xc0, 0xd5, 0x3c, 0xfe	; AND (SC1CR), 0feh	; IOC (bit 0) = 0: I/O interface input clock select = Baud rate generator
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	.byte 0x08, 0xeb, 0xdf	; LD (INTES1), 0dfh
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0xf0, 0xd4, 0x41	; LD (SC1BUF), A
	.byte 0x06, 0x00	; EI 000h
	nop
	ret


INTA_HANDLER:	; fc442b
	.byte 0xf1, 0x98, 0x8d, 0x00, 0x00	; LD (CPANEL_COUNTER_UP_TO_20), 000h
	push xwa
	.byte 0xc1, 0x8b, 0x8d, 0x3f, 0x00	; CP (CPANEL_PACKET_BYTE_COUNT), 000h
	.byte 0x6e, 0x2a	; JR NZ, LABEL_FC4462

	.byte 0xc1, 0x8e, 0x8d, 0x3c, 0x9f	; AND (PFCR_VALUE), 09fh
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0xc0, 0xd5, 0x3e, 0x01	; OR (SC1CR), 001h	; IOC (bit 0) = 1: Set I/O interface input clock select to SCLK1 pin
	.byte 0xc0, 0xd5, 0x3c, 0xfd	; AND (SC1CR), 0fdh	; SCLKS (bit 1) = 0: Data transmit/receive at SCLK1 rising edge.
	.byte 0x08, 0xe3, 0x05	; LD (INTEAB), 005h
	.byte 0x08, 0xeb, 0x0d	; LD (INTES1), 00dh
	.byte 0xc0, 0xd6, 0x3e, 0x20	; OR (SC1MOD), 020h	; parity addition: enable
	.byte 0xf1, 0x8a, 0x8d, 0x00, 0x20	; LD (CPANEL_STATE_MACHINE_INDEX), 020h	;		ROUTINE_7
	.byte 0xc1, 0x8c, 0x8d, 0x3e, 0x01	; OR (CPANEL_TX_RX_FLAGS), 001h	; CP_Flags_A.0 = 1
	.byte 0x68, 0x1c	; JR T, INTA_HANDLER_END

LABEL_FC4462:
	.byte 0xd1, 0x9f, 0x8d, 0x3f, 0x00, 0x00	; CPW (CPANEL_RX_WRITE_PTR), 0000h
	.byte 0x6e, 0x06	; JR NZ, LABEL_FC4470

	.byte 0xf1, 0x9f, 0x8d, 0x02, 0x5c, 0x00	; LDW (CPANEL_RX_WRITE_PTR), 005ch

LABEL_FC4470:
	.byte 0xd1, 0x9f, 0x8d, 0x69	; DECW 1, (CPANEL_RX_WRITE_PTR)
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x40	; OR (CPANEL_PROTOCOL_FLAGS), 040h	; CP_Flags_B.6 = 1  ; UNUSED
	.byte 0xc1, 0x8c, 0x8d, 0x3c, 0xfd	; AND (CPANEL_TX_RX_FLAGS), 0fdh	; CP_Flags_A.1 = 0

INTA_HANDLER_END:	; FC447E
	pop xwa
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	reti


CPANEL_STATE_MACHINE_TABLE:	; FC4489
	.long 0x00FC47E9	; DD CPanel_SM_Idle	;(offsets: 000h)  ; IDLE
	.long 0x00FC44F9	; DD CPanel_SM_StartTX	;(         004h)
	.long CPanel_SM_SendByte1
	.long CPanel_SM_TXDelay1
	.long CPanel_SM_SendByteN
	.long CPanel_SM_TXDelay2
	.long CPanel_SM_TXComplete
	.long 0x00FC47E9	; DD CPanel_SM_Idle	;(         01ch)
	.long CPanel_SM_RXByte1
	.long CPanel_SM_RXByteN
	.long 0x00FC47E9	; DD CPanel_SM_Idle	;(         028h)  ; UNREACHABLE_STATE (?)


INTTX1_HANDLER:	; FC44B5
	push xwa
	push xhl
	push xiy
	.byte 0xc1, 0x8a, 0x8d, 0x27	; LD L, (CPANEL_STATE_MACHINE_INDEX)
	xor h, h
	extz xhl
	.byte 0xeb, 0xc8, 0x89, 0x44, 0xfc, 0x00	; ADD XHL, CPANEL_STATE_MACHINE_TABLE
	ld xhl, (xhl)
	.byte 0xb3, 0xd8	; JP T, XHL


MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:	; FC44CA
	pop xiy
	pop xhl
	pop xwa
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	reti


INTRX1_HANDLER:	; FC44D7
	push xwa
	push xhl
	push xiy
	.byte 0xc1, 0x8a, 0x8d, 0x27	; LD L, (CPANEL_STATE_MACHINE_INDEX)
	xor h, h
	extz xhl
	.byte 0xeb, 0xc8, 0x89, 0x44, 0xfc, 0x00	; ADD XHL, CPANEL_STATE_MACHINE_TABLE
	ld xhl, (xhl)
	.byte 0xb3, 0xd8	; JP T, XHL

LEAST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES:	; FC44EC
	pop xiy
	pop xhl
	pop xwa
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xf8, 0x22	; LD (INTCLR), 022h	; INTRX1: Serial receive 1
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	reti


CPanel_SM_StartTX:	; FC44F9	; Start transmitting command to set LEDs on the control panel... (?)
	.byte 0xc1, 0x8e, 0x8d, 0x3c, 0xbf	; AND (PFCR_VALUE), 0bfh
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0x08, 0xd7, 0x24	; LD (BR1CR), 024h	; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	.byte 0x08, 0xe3, 0x07	; LD (INTEAB), 007h	; INTTRA(TREGA): M=7
	.byte 0x08, 0xeb, 0xd0	; LD (INTES1), 0d0h	; INTTX1: M=5
	.byte 0xc0, 0xd5, 0x3c, 0xfe	; AND (SC1CR), 0feh
	.byte 0xf0, 0xd4, 0x41	; LD (SC1BUF), A
	.byte 0xc1, 0x8a, 0x8d, 0x64	; INC 4, (CPANEL_STATE_MACHINE_INDEX)	; next = ROUTINE_2
	.byte 0xc9, 0x08, 0x01	; MUL_A 001h
	.byte 0xc9, 0x08, 0x01	; MUL_A 001h
	.byte 0xf0, 0x3c, 0xce	; BIT 6, (PF)	; PF.6 = state of SCLK1 pin
	.byte 0x6e, 0xa6	; JR NZ, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


						; If we receive a SCLK1 LOW, does it mean CPANEL is trying to spreak and we revert to IDLE state (ROUTINE_0) ?
	.byte 0xf1, 0x8b, 0x8d, 0x00, 0x00	; LD (CPANEL_PACKET_BYTE_COUNT), 000h
	.byte 0xf1, 0x8a, 0x8d, 0x00, 0x00	; LD (CPANEL_STATE_MACHINE_INDEX), 000h	; ROUTINE_0
	.byte 0xc1, 0x92, 0x8d, 0x3e, 0x02	; OR (CPANEL_PROTOCOL_FLAGS), 002h	; CP_Flags_B.1 = 1  ; UNUSED
	.byte 0x08, 0xe3, 0x05	; LD (INTEAB), 005h
	.byte 0x08, 0xeb, 0xff	; LD (INTES1), 0ffh
	.byte 0x08, 0xd7, 0x24	; LD (BR1CR), 024h	; Internal Clock T8 (64/fc)
	                 ; Divide by 4
	                 ; fc = 16MHz, so fc/64/4 = 62500
	.byte 0xc1, 0x8c, 0x8d, 0x3c, 0xfd	; AND (CPANEL_TX_RX_FLAGS), 0fdh	; CP_Flags_A.1 = 0
	.byte 0x78, 0x86, 0xff	; JRL T, MOST_COMMON_END_FOR_CPANEL_SERIAL_ROUTINES


CPanel_SM_TXDelay1:	; FC4544
