	.byte 0x68, 0x03	; JR T, LABEL_FC487A
				; } else {

LABEL_FC4877:
	.byte 0x1e, 0xb3, 0x02	; CALR CPanel_UpdateLEDs	; do this
				; }
LABEL_FC487A:
	.byte 0x06, 0x06	; EI 006h
	.byte 0xf0, 0x3c, 0xce	; BIT 6, (PF)	; PF.6 = state of SCLK1 pin
	.byte 0x66, 0x6a	; JR Z, LABEL_FC48EB
	.byte 0xf0, 0x38, 0xcd	; BIT 5, (PE)	; PE.5 = state of INTA pin
	.byte 0x6e, 0x65	; JR NZ, LABEL_FC48EB
	.byte 0xf1, 0x8c, 0x8d, 0xc9	; BIT 1, (CPANEL_TX_RX_FLAGS)
	.byte 0x6e, 0x5f	; JR NZ, LABEL_FC48EB
	.byte 0xf1, 0x8c, 0x8d, 0xc8	; BIT 0, (CPANEL_TX_RX_FLAGS)
	.byte 0x6e, 0x59	; JR NZ, LABEL_FC48EB

	; Only reaches here when (CPANEL_TX_RX_FLAGS), CP_Flags_A.10 == 00:
	.byte 0xd1, 0xff, 0x8d, 0x20	; LD WA, (CPANEL_LED_WRITE_PTR)
	.byte 0xd1, 0xfd, 0x8d, 0xa0	; SUB WA, (CPANEL_LED_READ_PTR)
	.byte 0x6f, 0x08	; JR NC, LABEL_FC48A4
	neg wa
	.byte 0xc8, 0xb9	; EX A, W
	.byte 0x21, 0x3c	; LD_A 03ch
	sub a, w

LABEL_FC48A4:
	.byte 0xc9, 0xda	; CP A, 2
	.byte 0x67, 0x40	; JR C, LABEL_FC48E8
	.byte 0xc1, 0x8c, 0x8d, 0x3e, 0x02	; OR (CPANEL_TX_RX_FLAGS), 002h	; CP_Flags_A.1 = 1
	.byte 0xf1, 0x8a, 0x8d, 0x00, 0x04	; LD (CPANEL_STATE_MACHINE_INDEX), 004h	; ROUTINE_1
	.byte 0xc1, 0x8f, 0x8d, 0x3c, 0xbf	; AND (PFFC_VALUE), 0bfh	; disable CPanel serial clk
	.byte 0xc1, 0x8f, 0x8d, 0x21	; LD A, (PFFC_VALUE)
	.byte 0xf0, 0x3f, 0x41	; LD (PFFC), A
	.byte 0xc0, 0x3c, 0x3c, 0xbf	; AND (PF), 0bfh	; PF bit 6, (SCLK1 | /CTS1) = 0
	.byte 0xc1, 0x8e, 0x8d, 0x3e, 0x40	; OR (PFCR_VALUE), 040h
	.byte 0xc1, 0x8e, 0x8d, 0x21	; LD A, (PFCR_VALUE)
	.byte 0xf0, 0x3e, 0x41	; LD (PFCR), A
	.byte 0x08, 0xd7, 0x28	; LD (BR1CR), 028h	; Internal Clock T8 (64/fc)
	                 ; Divide by 8
	                 ; fc = 16MHz, so fc/64/8 = 31250
	.byte 0xc0, 0xd6, 0x3c, 0xdf	; AND (SC1MOD), 0dfh	; RXE (bit 5) = 0: CPanel receive disable
	.byte 0xc0, 0xd5, 0x3c, 0xfe	; AND (SC1CR), 0feh
	.byte 0x08, 0xe3, 0x07	; LD (INTEAB), 007h
	.byte 0x08, 0xf8, 0x12	; LD (INTCLR), 012h	; INTA Pin
	.byte 0x08, 0xf8, 0x23	; LD (INTCLR), 023h	; INTTX1: Serial send 1
	.byte 0x08, 0xeb, 0xd0	; LD (INTES1), 0d0h
	.byte 0xf0, 0xd4, 0x41	; LD (SC1BUF), A

LABEL_FC48E8:
	.byte 0x06, 0x00	; EI 000h
	ret


LABEL_FC48EB:
	.byte 0xc1, 0x98, 0x8d, 0x61	; INC 1, (CPANEL_COUNTER_UP_TO_20)
	.byte 0xc1, 0x98, 0x8d, 0x3f, 0x14	; CP (CPANEL_COUNTER_UP_TO_20), 014h
	.byte 0x63, 0xf2	; JR ULE, LABEL_FC48E8

