; also serves to update the LEDs later on.
LABEL_FC7151:
	.byte 0xef, 0x68	; DEC 8, XSP
	.byte 0xd7, 0xfa, 0x04	; PUSH QIZ
	.byte 0xf1, 0x18, 0x8f, 0x30	; LDA XWA, ENCODER_STATE_BASE
	.byte 0xbf, 0x02, 0x60	; LD (XSP + 002h), XWA
	.byte 0xf1, 0x28, 0x8f, 0x30	; LDA XWA, 8F28h
	.byte 0xbf, 0x06, 0x60	; LD (XSP + 006h), XWA
	.byte 0xc1, 0x36, 0x8d, 0x3f, 0xf7	; CP (8D36h), 0f7h
	.byte 0x66, 0x41	; JR Z, LABEL_FC71AC
	.byte 0xc7, 0xfb, 0xa8	; LD QIZH, 0

LABEL_FC716E:
	.byte 0xc7, 0xfb, 0x89	; LD A, QIZH
	extz wa
	.byte 0xaf, 0x02, 0x21	; LD XBC, (XSP + 002h)
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x23	; LD C, (XBC + WA)
	.byte 0xc7, 0xfa, 0x9b	; LD QIZL, C
	.byte 0xaf, 0x06, 0x21	; LD XBC, (XSP + 006h)
	.byte 0xc3, 0x07, 0xe4, 0xe0, 0x23	; LD C, (XBC + WA)
	.byte 0xc7, 0xfa, 0xf3	; CP C, QIZL
	.byte 0x66, 0x18	; JR Z, LABEL_FC71A3
	.byte 0xc7, 0xfa, 0x8b	; LD C, QIZL
	extz bc
	.byte 0x1e, 0x1f, 0x00	; CALR Set_LEDs
	.byte 0xc7, 0xfb, 0x8d	; LD E, QIZH
	extz de
	.byte 0xaf, 0x06, 0x20	; LD XWA, (XSP + 006h)
	.byte 0xc7, 0xfa, 0x8b	; LD C, QIZL
	.byte 0xf3, 0x07, 0xe0, 0xe8, 0x43	; LD (XWA + DE), C

LABEL_FC71A3:
	.byte 0xc7, 0xfb, 0x61	; INC 1, QIZH
	.byte 0xc7, 0xfb, 0xcf, 0x0f	; CP QIZH, 00fh
	.byte 0x67, 0xc2	; JR C, LABEL_FC716E

LABEL_FC71AC:
	.byte 0xd7, 0xfa, 0x05	; POP QIZ
	.byte 0xef, 0x60	; INC 8, XSP
	ret


Set_LEDs:	; FC71B2
	; Input: WA: row of LEDs
	;         C: LED pattern
	ld e, a
	cp e, 0xF
	.byte 0xb0, 0xfb	; RET UGT
	.byte 0xf1, 0x38, 0x8f, 0x30	; LDA XWA, CPANEL_LEDS__ROW_AND_PATTERN_BYTES
	extz de
	.byte 0xf2, 0x16, 0xa6, 0xed, 0x33	; LDA XHL, Protocol_values_for_LED_rows
	.byte 0xc3, 0x07, 0xec, 0xe8, 0x25	; LD E, (XHL + DE)
	ld (xwa), e
	.byte 0xb8, 0x01, 0x43	; LD (XWA + 001h), C
	.byte 0x1e, 0x01, 0x00	; CALR LABEL_FC71D2
	ret

LABEL_FC71D2:
	push xiz
	ld xiz, xwa
	ld a, (xiz)
	extz wa
	.byte 0x28	; PUSH WA
	call LABEL_EF2B81
	inc 2, xsp
	cp hl, 0xFFFF
	.byte 0x6e, 0x10	; JR NZ, LABEL_FC71F6
	push xde
	push xhl
	push xix
	push xiz
	call LABEL_FC3ECC
	pop xiz
	pop xix
	pop xhl
	pop xde
	ld xwa, xiz
	.byte 0x68, 0x21	; JR T, LABEL_FC7217

LABEL_FC71F6:
	.byte 0x8e, 0x01, 0x21	; LD A, (XIZ + 001h)
	extz wa
	.byte 0x28	; PUSH WA
	call LABEL_EF2B81
	inc 2, xsp
	cp hl, 0xFFFF
	.byte 0x6e, 0x1a	; JR NZ, LABEL_FC7222
	push xde
	push xhl
	push xix
	push xiz
	call LABEL_FC3ECC
	pop xiz
	pop xix
	pop xhl
	pop xde
	.byte 0xbe, 0x01, 0x30	; LDA XWA, XIZ + 001h

LABEL_FC7217:
	ld a, (xwa)
	extz wa
	.byte 0x28	; PUSH WA
	call LABEL_EF2B81
	inc 2, xsp

LABEL_FC7222:
	pop xiz
	ret


